{
  "title": "A Day of Markets and Meals",
  "summary": "A slower day built around Coyoacán's market, Frida's house, and two proper meals with time to savour them.",
  "stops": [
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "The market stays: it is the snack-filled heart of the day, and the crew asked for more food.",
      "note_voice": "We start where the tortas steam and the fruit glistens: Coyoacán's market is the edible heart of today."
    },
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": null,
      "note": "Frida's house sits just a short stroll from the market, so the day stays in one leafy pocket of the city.",
      "note_voice": "A short amble from the market, Frida's blue house keeps us in the same lovely corner of the city."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper vegetarian-friendly meal in Roma Norte, added because the day needed more than one food stop.",
      "note_voice": "Lunch is a proper sit-down, with plenty for the vegetarians among us, because one food stop was never going to be enough."
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle walk after lunch keeps the pace easy and lets the crew digest while seeing Roma Norte.",
      "note_voice": "A gentle wander through Roma Norte lets lunch settle and the neighbourhood show off a little."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner stays in Roma Norte at Pujol, a long, proper meal to end the day.",
      "note_voice": "We finish with a long, proper dinner at Pujol, because today was always about eating well."
    }
  ]
}
